value.program:
def _known_bool(facts, key):
    value = facts.get(key, None)
    if isinstance(value, bool):
        return value
    return None


def _known_number(facts, key):
    value = facts.get(key, None)
    if isinstance(value, bool):
        return None
    if isinstance(value, (int, float)):
        return float(value)
    return None


def _bool_options(value):
    if isinstance(value, bool):
        return [value]
    return [False, True]


def _tri_and(values):
    for value in values:
        if value is False:
            return False
    for value in values:
        if value is None:
            return None
    return True


def _tri_or(values):
    for value in values:
        if value is True:
            return True
    for value in values:
        if value is None:
            return None
    return False


def _subject(question):
    match = re.search(r"applies\s+to\s+([A-Z][A-Za-z'-]*)", question)
    if match:
        return match.group(1)
    match = re.search(r"([A-Z][A-Za-z'-]*)(?:'s|’s)\s+additional\s+standard\s+deduction", question)
    if match:
        return match.group(1)
    return "the taxpayer"


def _kind(question):
    c6 = re.search(r"63\s*\(\s*c\s*\)\s*\(\s*6\s*\)\s*\(\s*A\s*\)", question, re.I)
    c3 = re.search(r"63\s*\(\s*c\s*\)\s*\(\s*3\s*\)", question, re.I)
    lower = question.lower()
    if c6 and ("apply" in lower or "applies" in lower or "applicable" in lower or "inapplicable" in lower):
        return "c6a"
    if c3 or "additional standard deduction" in lower:
        if re.search(r"\$\s*[0-9]", question):
            return "c3_amount"
    return "unsupported"


def _plan_c6a(subject):
    return {
        "taxpayer_married": {"type": "boolean", "question": "Does the case explicitly state that " + subject + " was married at the relevant close-of-year time?"},
        "legally_separated_under_decree": {"type": "boolean", "question": "Does the case explicitly state that " + subject + " was legally separated from the spouse under a decree of divorce or separate maintenance?"},
        "filed_separate_return": {"type": "boolean", "question": "Does the case explicitly state that " + subject + " filed a separate return for the taxable year?"},
        "taxpayer_itemized_deductions": {"type": "boolean", "question": "Does the case explicitly state that " + subject + " itemized deductions for the taxable year?"},
        "spouse_itemized_deductions": {"type": "boolean", "question": "Does the case explicitly state that " + subject + "'s spouse itemized deductions for the taxable year?"}
    }


def _plan_c3(subject):
    return {
        "stated_total_additional_standard_deduction_amount": {"type": "number", "question": "What total dollar amount of additional standard deduction does the case explicitly state for " + subject + "?"},
        "stated_self_additional_standard_deduction_amount": {"type": "number", "question": "What dollar amount of additional standard deduction does the case explicitly state " + subject + " is entitled to for herself or himself?"},
        "stated_spouse_additional_standard_deduction_amount": {"type": "number", "question": "What dollar amount of additional standard deduction does the case explicitly state " + subject + " is entitled to for the spouse?"},
        "taxpayer_married": {"type": "boolean", "question": "Does the case explicitly state that " + subject + " was married at the relevant close-of-year time?"},
        "legally_separated_under_decree": {"type": "boolean", "question": "Does the case explicitly state that " + subject + " was legally separated from the spouse under a decree of divorce or separate maintenance?"},
        "taxpayer_is_surviving_spouse": {"type": "boolean", "question": "Does the case explicitly state that " + subject + " was a surviving spouse for the taxable year?"},
