        "maintained_home_for_listed_child_dependent": {"type": "boolean", "question": "Does the case explicitly state that " + subject + " maintained a home that was the taxable-year principal abode of a dependent son, stepson, daughter, or stepdaughter?"},
        "furnished_over_half_home_cost": {"type": "boolean", "question": "Does the case explicitly state that " + subject + " furnished over half the cost of maintaining that household during the taxable year?"},
        "remarried_before_year_end": {"type": "boolean", "question": "Does the case explicitly state that " + subject + " had remarried before the close of the taxable year?"},
        "death_year_joint_return_possible": {"type": "boolean", "question": "Does the case explicitly state that " + subject + " and the deceased spouse could have made a joint return for the taxable year in which the spouse died?"},
        "taxpayer_attained_65_before_close": {"type": "boolean", "question": "Does the case explicitly state that " + subject + " attained age 65 before the close of the taxable year?"},
        "taxpayer_blind_at_close": {"type": "boolean", "question": "Does the case explicitly state that " + subject + " was blind at the close of the taxable year?"},
        "spouse_attained_65_before_close": {"type": "boolean", "question": "Does the case explicitly state that " + subject + "'s spouse attained age 65 before the close of the taxable year?"},
        "spouse_blind_at_required_time": {"type": "boolean", "question": "Does the case explicitly state that " + subject + "'s spouse was blind at the close of the taxable year, or at death if the spouse died during that year?"},
